import fs from 'node:fs';
const q = s => "'" + s.replace(/'/g, "'\\''") + "'";
const pool = [
 '--a','--b','--c','--d','--e','--f','-h','--help','--h','--he','--hel','--hell',
 '--a=1','--b=2','--c=3','--d=0','--e=-5','--f=6','--a=','--a=x','--a=-','--a=--',
 '--','--=','--=5','---a','---','--z','--A','-a','-abc','-q5','-','-5','-05','-5x','-x','--5','--0',
 '1','2','-1','0','x','','a b','- 5','-5 ',' -5','--b','--a','=','=5','--a==1','--a=1=2',
 '-h5','-hx','-h=','-h=3','--help=3','--hel=x','+a','/a','−5','--a 1',
];
let seed = Number(process.argv[2] || 12345);
function rnd(){ seed = (seed*1103515245 + 12345) & 0x7fffffff; return seed/0x7fffffff; }
const N = Number(process.argv[3] || 150);
const lines = [];
for(let i=0;i<N;i++){
  const n = 1 + Math.floor(rnd()*8);
  const parts=[];
  for(let j=0;j<n;j++) parts.push(q(pool[Math.floor(rnd()*pool.length)]));
  lines.push(parts.join(' '));
}
fs.writeFileSync(process.argv[4]||'gr.txt', lines.join('\n')+'\n');
EOF
