cd /tmp/argfuzz && cat > gen2.mjs <<'EOF'
import fs from 'node:fs';
const q = s => "'" + s.replace(/'/g, "'\\''") + "'";
let seed = Number(process.argv[2]||1);
function rnd(){ seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff; }
function pick(a){ return a[Math.floor(rnd()*a.length)]; }
const names=['a','b','c','d','e','f'];
const vals={a:'22',b:'64',c:'-64',d:'11',e:'-47',f:'10'};
const weird=['-5','-05','-5x','-x','-','- 5','-5 ',' -5','--b','--a','-h','--','x','','0','+3','1_0','-0.5','-.5','5.','０１２','٣','--z','=','1 ','\t7',' ','-1e3','--0','007','-007'];
const N=Number(process.argv[3]||120);
const lines=[];
for(let i=0;i<N;i++){
  // base: shuffled full set
  const order=names.slice();
  for(let k=order.length-1;k>0;k--){const j=Math.floor(rnd()*(k+1));[order[k],order[j]]=[order[j],order[k]];}
  let toks=[];
  for(const n of order){
    const style=rnd();
    if(style<0.5) toks.push('--'+n, vals[n]);
    else toks.push('--'+n+'='+vals[n]);
  }
  const nmut=1+Math.floor(rnd()*3);
  for(let m=0;m<nmut;m++){
    const op=Math.floor(rnd()*7);
    const pos=Math.floor(rnd()*(toks.length+1));
    if(op===0) toks.splice(pos,0,pick(weird));           // insert weird token
    else if(op===1) toks.splice(pos,1);                   // delete token
    else if(op===2) toks.splice(pos,0,'--');              // insert --
    else if(op===3) toks.splice(pos,0,'-h');              // insert -h
    else if(op===4){ const n=pick(names); toks.splice(pos,0,'--'+n, pick(weird)); }
    else if(op===5){ const n=pick(names); toks.splice(pos,0,'--'+n+'='+pick(weird)); }
    else if(op===6) toks.splice(pos,0,pick(['--h','--he','--hel','--help','--hell','-h5','-hx','-h=3','---a','--=','--=5','-abc']));
  }
  lines.push(toks.map(q).join(' '));
}
fs.writeFileSync(process.argv[4]||'gm.txt', lines.join('\n')+'\n');
EOF
